# Simplified Paxos Phase 1 (Prepare) pseudocode
def prepare(n, acceptors):
    promises = []
    for acceptor in acceptors:
        resp = acceptor.prepare(n)  # returns (promised_ballot, accepted_ballot, accepted_val)
        if resp.promised_ballot == n:
            promises.append(resp)
    if len(promises) >= majority(len(acceptors)):
        # Pick value from highest accepted ballot, or choose freely
        highest = max(promises, key=lambda r: r.accepted_ballot, default=None)
        return highest.accepted_val if highest and highest.accepted_val else MY_VALUE
    return None  # failed to get a majority

