class LamportClock:
    def __init__(self, node_id):
        self.counter = 0
        self.node_id = node_id

    def tick(self):
        self.counter += 1
        return (self.counter, self.node_id)

    def receive(self, remote_counter):
        # Advance past the remote's counter before recording the receive event
        self.counter = max(self.counter, remote_counter) + 1
        return (self.counter, self.node_id)

def vc_compare(va, vb):
    """Returns 'before', 'after', 'concurrent', or 'equal'"""
    a_le_b = all(va.get(n, 0) <= vb.get(n, 0) for n in set(va) | set(vb))
    b_le_a = all(vb.get(n, 0) <= va.get(n, 0) for n in set(va) | set(vb))
    if a_le_b and b_le_a:
        return 'equal'
    elif a_le_b:
        return 'before'  # va happened-before vb
    elif b_le_a:
        return 'after'
    else:
        return 'concurrent'  # conflict — neither dominates

# Storage node that enforces epoch-based fencing
class FencedStorage:
    def __init__(self):
        self.data = {}
        self.max_epoch = 0

    def write(self, key, value, epoch):
        if epoch < self.max_epoch:
            raise StaleLeaderError(f"epoch {epoch} < max seen {self.max_epoch}")
        self.max_epoch = epoch
        self.data[key] = value

