import hashlib
import math

class CountMinSketch:
    """Approximate frequency counter with bounded overcount error."""

    def __init__(self, epsilon: float = 0.01, delta: float = 0.01):
        self.w = math.ceil(math.e / epsilon)  # columns
        self.d = math.ceil(math.log(1 / delta))  # rows
        self.table = [[0] * self.w for _ in range(self.d)]

    def _hashes(self, item: str):
        for i in range(self.d):
            h = int(hashlib.md5(f'{i}:{item}'.encode()).hexdigest(), 16)
            yield h % self.w

    def add(self, item: str):
        for row, col in enumerate(self._hashes(item)):
            self.table[row][col] += 1

    def query(self, item: str) -> int:
        return min(self.table[row][col] for row, col in enumerate(self._hashes(item)))

def dominates(va, vb):
    """Returns True if version vector va causally dominates vb."""
    all_nodes = set(va) | set(vb)
    return (
        all(va.get(n, 0) >= vb.get(n, 0) for n in all_nodes)
        and any(va.get(n, 0) > vb.get(n, 0) for n in all_nodes)
    )

def are_concurrent(va, vb):
    """Returns True if va and vb are concurrent (conflict required)."""
    return not dominates(va, vb) and not dominates(vb, va)
